using CommunityToolkit.Maui.Behaviors;
using MathSolver.Services;

namespace MathSolver.Controls;

/// <summary>
/// Tints the original image at runtime without separate light/dark assets.
/// SVG resources use the PNG name generated by MAUI's image build pipeline.
/// </summary>
public sealed class ThemedImageIcon : Image
{
    public static readonly BindableProperty FollowWallpaperContrastProperty =
        BindableProperty.Create(
            nameof(FollowWallpaperContrast), typeof(bool), typeof(ThemedImageIcon), false,
            propertyChanged: (bindable, _, _) => ((ThemedImageIcon)bindable).RefreshThemeColor());

    private readonly IconTintColorBehavior _tintBehavior = new();
    private bool _isThemeSubscribed;

    public ThemedImageIcon()
    {
        Aspect = Aspect.AspectFit;
        InputTransparent = true;
        Behaviors.Add(_tintBehavior);
        Loaded += OnLoaded;
        Unloaded += OnUnloaded;
        RefreshThemeColor();
    }

    public bool FollowWallpaperContrast
    {
        get => (bool)GetValue(FollowWallpaperContrastProperty);
        set => SetValue(FollowWallpaperContrastProperty, value);
    }

    private void OnLoaded(object? sender, EventArgs e)
    {
        if (!_isThemeSubscribed)
        {
            AppThemeManager.ThemeChanged += OnThemeChanged;
            AppThemeManager.WallpaperVisualResourcesChanged += OnWallpaperContrastChanged;
            _isThemeSubscribed = true;
        }

        RefreshThemeColor();
    }

    private void OnUnloaded(object? sender, EventArgs e)
    {
        if (!_isThemeSubscribed) return;

        AppThemeManager.ThemeChanged -= OnThemeChanged;
        AppThemeManager.WallpaperVisualResourcesChanged -= OnWallpaperContrastChanged;
        _isThemeSubscribed = false;
    }

    // Both notifications are raised by AppThemeManager on the UI thread.
    private void OnThemeChanged(object? sender, EventArgs e) => RefreshThemeColor();

    private void OnWallpaperContrastChanged(object? sender, EventArgs e)
    {
        if (FollowWallpaperContrast) RefreshThemeColor();
    }

    public void RefreshThemeColor()
    {
        _tintBehavior.TintColor = FollowWallpaperContrast
            ? AppThemeManager.WallpaperMonochromeIconColor
            : AppThemeManager.MonochromeIconColor;
    }
}
